var active=state.machines.filter(function(m){return m.status!=='Inactive';}),closed=state.dailyClosings.filter(function(x){return x.date===today();}),missing=active.filter(function(m){return !closed.some(function(x){return x.machineId===m.id;});});
body='<div class="mach-kpis"><article><small>Active machines</small><b>'+active.length+'</b></article><article><small>Closed today</small><b>'+closed.length+'</b></article><article><small>Outstanding</small><b>'+missing.length+'</b></article></div><div class="mach-panel"><h3>Daily closing · '+today()+'</h3><p class="mach-note">Every active machine needs a closing. Record No Operation Today when it did not work. Normal closings await owner reconciliation.</p>'+missing.map(function(m){return '<div class="mach-record"><b>'+esc(m.name)+'</b><span>'+esc(m.plate||m.type)+'</span></div>';}).join('')+'</div><div class="mach-panel"><h3>Record closing</h3><form id="dailyClosingForm" class="mach-form"><label>Machine<select name="machineId" required>'+machineOptions()+'</select></label><div class="mach-two"><label>Date<input name="date" type="date" value="'+today()+'" required></label><label>Type<select name="closingType"><option value="normal">Normal closing</option><option value="no-operation">No Operation Today</option></select></label></div><label>Actual cash held by driver<input name="actualCash" type="number" min="0" step=".01" value="0"></label><label>Reason / notes<input name="reason" required></label><button class="primary">Save daily closing</button></form></div><div class="mach-panel"><h3>Closing history</h3>'+state.dailyClosings.slice().sort(sortDate).map(function(x){return '<div class="mach-record"><b>'+esc((machine(x.machineId)||{}).name||'Machine')+' · '+esc(x.date)+' · '+(x.closingType==='no-operation'?'No Operation Today':'Normal')+'</b><span>Expected '+money(x.expectedCash)+' · Actual '+money(x.actualCash)+' · '+esc(x.status)+'</span><span>'+esc(x.reason||'')+'</span>'+(x.closingType==='normal'&&x.status!=='reconciled'?'<button type="button" class="primary" data-closing-reconcile="'+esc(x.id)+'">Reconcile</button>':'')+'</div>';}).join('')+'</div>';
