function integrityIssues(){var issues=[];state.machines.forEach(function(m){if(m.driverId){var d=driver(m.driverId);if(!d)issues.push('Machine '+m.name+' refers to a missing driver.');else{if(d.machineId!==m.id)issues.push('Driver assignment mismatch: '+d.name+'.');if(d.type!==m.type)issues.push('Driver type does not match machine type: '+d.name+'.');}}});state.drivers.forEach(function(d){if(d.machineId){var m=machine(d.machineId);if(!m)issues.push('Driver '+d.name+' refers to a missing machine.');else if(m.driverId!==d.id)issues.push('Machine register does not confirm driver assignment: '+d.name+'.');}});state.trips.forEach(function(t){if(!machine(t.machineId))issues.push('Trip '+(t.ticket||t.id)+' has no valid machine.');if(!customer(t.customerId))issues.push('Trip '+(t.ticket||t.id)+' has no valid customer.');if(tripPaid(t.id)>(Number(t.amount)||0)+0.005)issues.push('Trip '+(t.ticket||t.id)+' has receipts above its charge.');});state.payments.forEach(function(p){var sum=(p.allocations||[]).reduce(function(n,a){var t=byKind('trip',a.tripId);if(!t)issues.push('Payment '+(p.reference||p.id)+' allocates to a missing trip.');else if(t.customerId!==p.customerId||t.machineId!==p.machineId)issues.push('Payment '+(p.reference||p.id)+' allocates to the wrong customer or machine.');return n+(Number(a.amount)||0);},0);if(sum>(Number(p.amount)||0)+0.005)issues.push('Payment '+(p.reference||p.id)+' is over-allocated.');});state.expenses.forEach(function(x){if(!machine(x.machineId))issues.push('Expense '+x.id+' has no valid machine.');if(x.type==='Driver wages'&&x.driverId){var d=driver(x.driverId);if(!d||d.machineId!==x.machineId)issues.push('Payroll '+(x.period||x.id)+' has an invalid driver/machine assignment.');var expected=(Number(x.baseSalary)||0)+(Number(x.incentiveAmount)||0)-(Number(x.advance)||0)-(Number(x.deductions)||0);if(Math.abs(expected-(Number(x.amount)||0))>0.02)issues.push('Payroll total does not match its salary breakdown for '+(d?d.name:x.driverName||'driver')+'.');}});state.maintenance.forEach(function(x){if(x.status==='Completed'&&!state.expenses.some(function(e){return e.id===x.id;}))issues.push('Completed maintenance '+x.id+' has no matching expense.');});return issues;}
function downloadHtml(filename,html){var blob=new Blob([html],{type:'text/html;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(url);},30000);}
function sortDate(a,b){return String(b.date||'').localeCompare(String(a.date||''));}
function driverHeldBalance(driverId,machineId,upto){var n=0;state.payments.forEach(function(p){if(p.collectorDriverId===driverId&&(!machineId||p.machineId===machineId)&&(!upto||p.date<=upto))n+=Number(p.amount)||0;});state.driverLedger.forEach(function(x){if(x.driverId!==driverId||(machineId&&x.machineId!==machineId)||(upto&&x.date>upto)||x.status==='pending'||x.status==='rejected')return;if(x.type==='advance')n+=Number(x.amount)||0;else if(x.type==='expense-held'||x.type==='handover'||x.type==='advance-return')n-=Number(x.amount)||0;});return Math.round(n*100)/100;}
function driverPayable(driverId,upto){var n=0;state.driverLedger.forEach(function(x){if(x.driverId!==driverId||(upto&&x.date>upto)||x.status==='pending'||x.status==='rejected')return;if(x.type==='personal-expense')n+=Number(x.amount)||0;else if(x.type==='reimbursement')n-=Number(x.amount)||0;});return Math.max(0,Math.round(n*100)/100);}
function driverEarned(driverId){return total(state.trips.filter(function(t){return t.driverId===driverId;}));}
function driverCollected(driverId){return total(state.payments.filter(function(p){return p.collectorDriverId===driverId;}));}
function machineOptions(){return '<option value="">Choose machine</option>'+state.machines.filter(function(m){return m.status!=='Inactive';}).map(function(m){return '<option value="'+esc(m.id)+'">'+esc(m.name)+' · '+esc(m.plate||m.type)+'</option>';}).join('');}
function tripRows(rows){if(!rows.length)return '<p class="mach-note">No trip records yet.</p>';return rows.map(function(t){var m=machine(t.machineId),c=customer(t.customerId),d=driver(t.driverId);return '<div class="mach-record"><div class="mach-record-top"><b>'+esc(t.ticket||'Trip')+' · '+money(t.amount)+'</b><small>'+esc(t.date)+'</small></div><span>'+esc(m?m.name:'Machine')+' · '+esc(c?c.name:'Customer')+'</span><span>'+esc(t.material)+' · '+(Number(t.tripCount)||1)+' trip(s)'+(t.quantity?' · '+esc(t.quantity)+' '+esc(t.unit):'')+'</span><span>'+esc(t.origin||'')+' → '+esc(t.destination||'')+'</span><span>Driver: '+esc(d?d.name:'Not assigned')+'</span><span>Rate: '+money(t.rate)+' '+esc(t.basis==='trip'?'per trip':t.basis==='tonne'?'per tonne':'per m³')+'</span><span>'+tripStatus(t)+' · Paid '+money(tripPaid(t.id))+' · Due '+money(tripDue(t))+'</span>'+editButton('trip',t.id)+'</div>';}).join('');}

function editButton(kind,id){return '<button type="button" class="secondary" data-edit-kind="'+kind+'" data-edit-id="'+esc(id)+'">Edit</button>';}
function contactField(label,name,value){return field(label,name,value,'tel')+'<button type="button" data-pick-contact="'+name+'">📱 Choose from phone</button>';}
function field(label,name,value,type){return '<label>'+label+'<input name="'+name+'" type="'+(type||'text')+'" value="'+esc(value==null?'':value)+'"></label>';}
function pick(label,name,items,value){return '<label>'+label+'<select name="'+name+'">'+items.map(function(x){return '<option value="'+esc(x.value)+'" '+(String(x.value)===String(value)?'selected':'')+'>'+esc(x.label)+'</option>';}).join('')+'</select></label>';}
