// Capture the edit form before other app handlers. This avoids WebView form
// submission quirks and verifies that the updated machinery state reached storage.
document.addEventListener('submit',async function(e){
 var f=e.target;
 if(!f||f.getAttribute('id')!=='editRecordForm')return;
 e.preventDefault();e.stopImmediatePropagation();
 try{
  var v={};new FormData(f).forEach(function(value,key){if(!(value instanceof File))v[key]=String(value).trim();});
  v.tripIds=Array.from(f.elements.tripIds?f.elements.tripIds.selectedOptions:[]).map(function(o){return o.value;});
  if(v.kind==='expense')v.fullTank=!!(f.elements.fullTank&&f.elements.fullTank.checked);
  if(v.kind==='driver'){var current=byKind('driver',v.id);for(var photoName of ['idPhotoFront','idPhotoBack','licencePhoto']){var selected=f.elements[photoName]&&f.elements[photoName].files[0];if(selected)v[photoName]=await imageData(selected);else if(current)v[photoName]=current[photoName]||'';}}
  var existing=byKind(v.kind,v.id),before=existing?auditSnapshot(existing):null;
  if(!updateRecord(v.kind,v.id,v)){alert('Changes were not saved. Please check the required fields and try again.');return;}
  var serialized=JSON.stringify(state);
  localStorage.setItem(KEY,serialized);
  if(localStorage.getItem(KEY)!==serialized)throw new Error('Storage verification failed');
  var updated=byKind(v.kind,v.id);logAudit('Edited',v.kind,updated,before);save();
  editing=null;render();alert('Changes saved successfully.');
 }catch(err){alert('Save failed. Your existing records have not been intentionally deleted. Please check available phone storage and try again.');}
},true);
